        "CREATE OR REPLACE FUNCTION qrm_ad_material_reference_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN \n        INSERT INTO read_bucket_state\n            (tenant_id,advertiser_id,kind,bucket,source_revision,derived_revision,observed_at)\n        SELECT keys.tenant_id,keys.advertiser_id,keys.kind,keys.bucket,1,1,clock_timestamp()\n        FROM (SELECT DISTINCT tenant_id,advertiser_id,'usage'::varchar AS kind,DATE '1970-01-01' AS bucket FROM (SELECT DISTINCT tenant_id,advertiser_id,ad_remote_id,platform_material_id,material_type FROM new_rows) k) keys JOIN advertiser_account account\n            ON account.tenant_id=keys.tenant_id AND account.advertiser_id=keys.advertiser_id\n        ORDER BY keys.tenant_id,keys.advertiser_id,keys.kind,keys.bucket\n        ON CONFLICT (tenant_id,advertiser_id,kind,bucket) DO UPDATE SET\n            source_revision=read_bucket_state.source_revision+1,\n            observed_at=clock_timestamp(),derived_revision=read_bucket_state.source_revision+1;\n    \n        DELETE FROM current_ad_material target USING (SELECT DISTINCT tenant_id,advertiser_id,ad_remote_id,platform_material_id,material_type FROM new_rows) k\n        WHERE target.tenant_id=k.tenant_id AND target.advertiser_id=k.advertiser_id\n            AND target.ad_remote_id=k.ad_remote_id AND target.platform_material_id=k.platform_material_id\n            AND target.material_type=k.material_type;\n        INSERT INTO current_ad_material (id,tenant_id,advertiser_id,ad_remote_id,platform_material_id,ad_material_id,material_type,name,operation_status,complete,published_version)\n        WITH candidates AS (\n            SELECT u.*,bool_or(u.ad_material_id IS NOT NULL) OVER (\n                PARTITION BY u.tenant_id,u.advertiser_id,u.ad_remote_id,u.platform_material_id,u.material_type\n            ) AS has_precise\n            FROM (SELECT DISTINCT tenant_id,advertiser_id,ad_remote_id,platform_material_id,material_type FROM new_rows) k JOIN ad_material_reference u ON u.tenant_id=k.tenant_id\n                AND u.advertiser_id=k.advertiser_id AND u.ad_remote_id=k.ad_remote_id\n                AND u.platform_material_id=k.platform_material_id AND u.material_type=k.material_type\n            WHERE u.complete\n        ), preferred AS (\n            SELECT *,max(published_version) OVER (\n                PARTITION BY tenant_id,advertiser_id,ad_remote_id,platform_material_id,material_type\n            ) AS newest FROM candidates WHERE NOT has_precise OR ad_material_id IS NOT NULL\n        ) SELECT id,tenant_id,advertiser_id,ad_remote_id,platform_material_id,ad_material_id,material_type,name,operation_status,complete,published_version FROM preferred WHERE published_version=newest;\n     RETURN NULL; END $$"
